Translate("ptBR", "silverpine-forest", {
	title = "Floresta de Pinhaprata",
	aliases = { "Pinhaprata" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Floresta de Pinhaprata se estende para o sul, das clareiras de {link:tirisfal-glades}Tirisfal{/link} até a grande muralha de {link:gilneas}Gilneas{/link}. Pinheiros escuros se amontoam em suas colinas e, a leste, suas margens descem para as águas cinzentas do {red:lordamere-lake}Espelho de Lordaeron{/red}. Outrora era uma terra tranquila de fazendas, pomares e moinhos. Agora é uma terra dos mortos e dos amaldiçoados. Os {link:forsaken}Renegados{/link} dominam suas estradas a partir do {link:the-sepulcher}Sepulcro{/link}, o {link:scourge}Flagelo{/link} domina uma fortaleza numa ilha do lago, e nas colinas uivam os homens-lobo de um arquimago louco de {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra o ano em que os primeiros humanos se estabeleceram em Pinhaprata, nem qual senhor a reivindicou primeiro. Seu povo cultivava os vales, cuidava dos pomares e trabalhava nos moinhos. Acima do povoado de {link:pyrewood-village}Lenhardente{/link} erguia-se a fortaleza do nobre {link:baron-silverlaine}Barão Silverlaine{/link}. Quando o Rei {link:genn-greymane}Genn Greymane{/link} fechou seu reino depois da {link:second-war}Segunda Guerra{/link}, a {link:the-greymane-wall}Muralha Greymane{/link} se ergueu através do sul da floresta, e os portões de {link:gilneas}Gilneas{/link} se fecharam atrás dela. O povo de Pinhaprata ficou do lado norte.]=],
		},
		{
			title = "Os Dias Atuais",
			text = [=[A Dama Sombria deu a seu tenente {link:varimathras}Varimathras{/link} a tarefa de tomar as terras do sul, e Pinhaprata é o primeiro passo. O {link:high-executor-hadrec}Alto Executor Hadrec{/link} comanda os {link:forsaken}Renegados{/link} no {link:the-sepulcher}Sepulcro{/link}, mas seus inimigos são muitos. {link:gnolls}Gnolls{/link} Couro Podre, erguidos e presos pelo mago traidor {link:thule-ravenclaw}Thule Ravenclaw{/link}, carregam cadáveres de {link:tirisfal-glades}Tirisfal{/link} até a {link:fenris-isle}Ilha de Fenris{/link}. Os worgens do {link:archmage-arugal}Arquimago Arugal{/link} caçam na mata, e os aldeões de {link:pyrewood-village}Lenhardente{/link} se transformam em feras toda noite. Em {link:ambermill}Lenhâmbar{/link}, os {link:the-wizards-of-ambermill}magos de Dalaran{/link} trabalham num segredo próprio e guardam as estradas com mão pesada. Na {link:the-greymane-wall}Muralha Greymane{/link}, refugiados humanos assustados se reúnem diante de portões que não se abrirão.

Nestes dias, os paladinos da {link:tyr-s-watch}Tyr's Watch{/link} enviaram um agente ao Sepulcro, e uma viajante dos {link:skyborne}Skyborne{/link} chegou à floresta, trazendo luto consigo.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Os {link:forsaken}Renegados{/link}.{/b} Guardas da Morte, sicários, boticários e um arquimago morto de {link:dalaran}Dalaran{/link}, todos servindo à Dama Sombria a partir do {link:the-sepulcher}Sepulcro{/link}.
• {b}O {link:scourge}Flagelo{/link}.{/b} Os gnolls Couro Podre, os servos de {link:thule-ravenclaw}Thule Ravenclaw{/link} e os mortos sem mente das velhas fazendas.
• {b}Os worgens.{/b} Os Moonrage e os Filhos de {link:archmage-arugal}Arugal{/link}, homens-lobo selvagens que respondem, em parte, ao arquimago da {link:shadowfang-keep}Bastilha da Presa Negra{/link}.
• {b}Os {link:pyrewood-villagers}amaldiçoados de Lenhardente{/link}.{/b} Aldeões que são humanos de dia e feras à noite.
• {b}Os magos de {link:ambermill}Lenhâmbar{/link}.{/b} Magos do {link:kirin-tor}Kirin Tor{/link} e seus guardas, amigos nem dos vivos nem dos mortos do norte.
• {b}Feras e murlocs.{/b} Worgs, ursos grisalhos, grandes aranhas e os {link:murlocs}murlocs{/link} Vile Fin da margem do lago.]=],
		},
		{
			title = "História",
			text = [=[• {b}A Praga.{/b} Na {link:third-war}Terceira Guerra{/link}, a praga varreu {link:lordaeron}Lordaeron{/link}. Os fazendeiros do norte de Pinhaprata morreram em suas terras e se ergueram entre o {link:scourge}Flagelo{/link}.
• {b}Os Worgens.{/b} Os {link:the-wizards-of-ambermill}magos de Dalaran{/link} combateram o Flagelo na floresta, e seus próprios mortos se ergueram contra eles. Contra o conselho de seus pares, o {link:archmage-arugal}Arquimago Arugal{/link} invocou poderes de além do mundo, e os worgens vieram. Massacraram os mortos, e depois se voltaram contra os magos. Tomaram a fortaleza do {link:baron-silverlaine}Barão Silverlaine{/link}, e Arugal a fez sua.
• {b}Os {link:forsaken}Renegados{/link}.{/b} Com o tempo, os Renegados vieram de {link:tirisfal-glades}Tirisfal{/link} para o sul e fizeram do {link:the-sepulcher}Sepulcro{/link} sua fortaleza na floresta.]=],
		},
		{
			title = "O Saber da Floresta",
			text = [=[• Os boticários dizem que, há eras, uma praga matou todos os seres vivos nas águas do Espelho de {link:lordaeron}Lordaeron{/link}.
• Três jovens magos teceram certa vez uma única varinha a partir de suas varinhas de aprendiz, como sinal de amizade. Um deles era {link:thule-ravenclaw}Thule Ravenclaw{/link}.
• Um arquimago morto no {link:the-sepulcher}Sepulcro{/link} afirma que {link:archmage-arugal}Arugal{/link} jamais teve poder para criar um worgen sequer.]=],
		},
	},
})

Translate("ptBR", "the-sepulcher", {
	title = "O Sepulcro",
	aliases = { "Sepulcro", "Sepulcro de Pinhaprata" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Sepulcro é a fortaleza dos {link:forsaken}Renegados{/link} em {link:silverpine-forest}Pinhaprata{/link}. Fica numa colina arborizada no coração da floresta, um antigo cemitério onde os mortos agora vigiam o mundo dos vivos. Daqui o {link:high-executor-hadrec}Alto Executor Hadrec{/link} envia seus sicários, e os Guardas da Morte guardam as estradas. Um arquimago morto estuda a maldição dos worgens, um sacerdote das sombras reúne cada migalha de notícia, e um boticário da Sociedade trabalha na nova praga. Morcegos levam cavaleiros ao norte, até a {link:undercity}Cidade Baixa{/link}. Nestes dias o Sepulcro também abriga um enviado da {link:tyr-s-watch}Tyr's Watch{/link} e uma jovem dos {link:skyborne}Skyborne{/link}.]=],
		},
	},
})

Translate("ptBR", "pyrewood-village", {
	title = "Vilarejo Lenhardente",
	aliases = { "Lenhardente" },
	sections = {
		{
			title = "Resumo",
			text = [=[Lenhardente é um pequeno vilarejo no sul de {link:silverpine-forest}Pinhaprata{/link}, abaixo das muralhas da {link:shadowfang-keep}Bastilha da Presa Negra{/link}. De dia parece qualquer outro povoado humano: uma prefeitura, uma estalagem, ferreiros e alfaiates no trabalho e vigias nas ruas. Quando o sol se põe, seu povo se torna worgen. {link:archmage-arugal}Arugal{/link} pôs grilhões encantados em todos eles, e governa o vilarejo por meio de seu próprio conselho, cujos membros são seus fantoches. Na estalagem fica o estúdio de um boticário que caiu vítima da mesma maldição. Um sicário se esconde na prefeitura, esperando que o conselho volte para casa.]=],
		},
	},
})

Translate("ptBR", "ambermill", {
	title = "Lenhâmbar",
	sections = {
		{
			title = "Resumo",
			text = [=[Lenhâmbar é um vilarejo nas colinas do sudeste de {link:silverpine-forest}Pinhaprata{/link}, perto da margem do Espelho de {link:lordaeron}Lordaeron{/link}. Nunca foi um lugar importante. Ainda assim os magos de {link:dalaran}Dalaran{/link} o encheram de feiticeiros, conjuradores e guardiões armados, e enviam para lá caixotes de mapas e pingentes rúnicos em carroças vindas de {link:hillsbrad-foothills}Eira dos Montes{/link}. Os {link:forsaken}Renegados{/link} acreditam saber o porquê. Lenhâmbar fica sobre um nodo adormecido de energia de linhas de ley, e um arquimago tem trabalhado para despertá-lo. O que o {link:kirin-tor}Kirin Tor{/link} pretende fazer com tal poder, ninguém no {link:the-sepulcher}Sepulcro{/link} sabe dizer.]=],
		},
	},
})

Translate("ptBR", "fenris-isle", {
	title = "Ilha de Fenris",
	sections = {
		{
			title = "Resumo",
			text = [=[A Ilha de Fenris fica no Espelho de {link:lordaeron}Lordaeron{/link}, a leste dos {link:the-decrepit-ferry}Campos Apodrecidos{/link}. É a fortaleza do {link:scourge}Flagelo{/link} em {link:silverpine-forest}Pinhaprata{/link}. Os gnolls Couro Podre enxameiam suas margens e sua fortaleza em ruínas. Um barco traz os cadáveres de {link:tirisfal-glades}Tirisfal{/link} pela água a partir da balsa, e na ilha esses cadáveres servem a seu novo senhor. {link:murlocs}Murlocs{/link} Vile Fin caçam em suas praias, e feras do lago cobertas de musgo rastejam entre os juncos. Ultimamente os Guardas da Morte viram os gnolls jogarem um grande corpo numa pira junto à margem. Era o corpo de um {link:tauren}tauren{/link}.]=],
		},
	},
})

Translate("ptBR", "fenris-keep", {
	title = "Castelo Fenris",
	sections = {
		{
			title = "Resumo",
			text = [=[O Castelo Fenris é a fortaleza da {link:fenris-isle}Ilha de Fenris{/link}. {link:thule-ravenclaw}Thule Ravenclaw{/link} governa ali com seus gnolls Couro Podre. Em seu pátio, perto do velho estábulo, os gnolls enterraram um corpo sem cabeça numa cova sem marca. Guardaram a cabeça como brinquedo. Ela ainda fala. Alaric, o servo-chefe de Thule, passou os melhores dias de sua vida neste castelo e conhece seus segredos, entre eles um nicho escondido na torre sudoeste. Ultimamente os gnolls também mantêm um prisioneiro vivo numa jaula dentro das muralhas.]=],
		},
	},
})

Translate("ptBR", "the-decrepit-ferry", {
	title = "Campos Apodrecidos",
	aliases = { "balsa decrépita" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Campos Apodrecidos são um velho atracadouro na margem do Espelho de {link:lordaeron}Lordaeron{/link}, a leste do {link:the-sepulcher}Sepulcro{/link}. É podre e quase esquecido, mas não está ocioso. Servos de {link:thule-ravenclaw}Thule Ravenclaw{/link} o guardam, e gnolls Couro Podre vêm e vão. No barco ali atracado jazem pilhas de corpos embrulhados para viagem. Do outro lado da água, um segundo cais fica na {link:fenris-isle}Ilha de Fenris{/link}. Os {link:forsaken}Renegados{/link} descobriram que os corpos vêm das valas comuns de {link:tirisfal-glades}Tirisfal{/link}, entre eles uma mulher de {link:brill}Montalvo{/link} chamada Deliah, e que todos terminam sua viagem na ilha.]=],
		},
	},
})

Translate("ptBR", "the-dead-field", {
	title = "Campo Morto",
	aliases = { "Campos Mortos" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Campo Morto é uma fazenda abandonada no norte de {link:silverpine-forest}Pinhaprata{/link}. Os gnolls Couro Podre fizeram dela um acampamento, e os sicários que o vigiavam acharam que os gnolls se preparavam para a guerra. Os {link:forsaken}Renegados{/link} os atacaram mais de uma vez, e em cada uma foram derrotados por uma banshee chamada Nightlash, que veio em auxílio dos gnolls com sua magia. {link:high-executor-hadrec}Hadrec{/link} queria que ela fosse destruída. Dizem que, quando Nightlash cai, sua essência vira pó.]=],
		},
	},
})

Translate("ptBR", "the-ivar-patch", {
	title = "Plantação do Ivar",
	sections = {
		{
			title = "Resumo",
			text = [=[A Plantação do Ivar foi a fazenda de um homem chamado {link:ivar-the-foul}Ivar{/link}, no extremo norte de {link:silverpine-forest}Pinhaprata{/link}. Quando a praga chegou, Ivar, a maior parte de sua família e seus trabalhadores caíram todos e se ergueram de novo entre o {link:scourge}Flagelo{/link}. Ivar ainda assombra seu celeiro como carniçal. Os sicários {link:rane-yorick}Rane{/link} e {link:quinn-yorick}Quinn Yorick{/link} foram emboscados aqui em sua missão, e fizeram da velha casa dele seu abrigo. De suas janelas Rane monta guarda, enquanto Quinn se recupera no andar de cima.]=],
		},
	},
})

Translate("ptBR", "malden-s-orchard", {
	title = "Horto dos Maldonado",
	sections = {
		{
			title = "Resumo",
			text = [=[O Horto dos Maldonado fica no extremo nordeste de {link:silverpine-forest}Pinhaprata{/link}, perto da fronteira de {link:tirisfal-glades}Tirisfal{/link}. Suas árvores estão sem colheita, e quem morava em seu chalé se foi. Worgs agora enchem o horto, tantos que um sicário enviado para explorá-lo ficou preso dentro do chalé por dias. Os worgs vigiavam a porta e esperavam que ele saísse. Entre eles caça um grande worg negro conhecido como Gorefang.]=],
		},
	},
})

Translate("ptBR", "valgan-s-field", {
	title = "Sítio do Valgan",
	sections = {
		{
			title = "Resumo",
			text = [=[O Sítio do Valgan é uma fazenda de trigo no norte de {link:silverpine-forest}Pinhaprata{/link}, logo ao norte de uma ponte sobre um pequeno rio. Quando o {link:archmage-arugal}Arquimago Arugal{/link} chegou à floresta, foi aqui que se hospedou. Deixou para trás livros de feitiços, e os sicários que os encontraram não conseguiram levá-los. Entre eles havia um feitiço que Arugal chamava de seu remédio. Worgens agora vagam pelas terras em volta da fazenda.]=],
		},
	},
})

Translate("ptBR", "north-tide-s-hollow", {
	title = "Atracadouro da Maré do Norte",
	sections = {
		{
			title = "Resumo",
			text = [=[O Atracadouro da Maré do Norte é um trecho de mata logo ao norte do {link:the-sepulcher}Sepulcro{/link}, rumo ao mar do oeste. Os worgens Moonrage fizeram dele um de seus covis. Seus glutões e suas almas-sombrias rondam entre as árvores, e cada um usa um grilhão encantado feito por {link:archmage-arugal}Arugal{/link}. O arquimago morto do Sepulcro estudou esses grilhões de perto. Foram a primeira prova, diz ele, de que a magia de Arugal era mais fraca do que o mundo acreditava.]=],
		},
	},
})

Translate("ptBR", "olsen-s-farthing", {
	title = "Miséria de Olsen",
	sections = {
		{
			title = "Resumo",
			text = [=[A Miséria de Olsen é uma fazenda em ruínas junto à estrada principal, ao sul do {link:the-sepulcher}Sepulcro{/link}. Outrora fazia negócio com toda carroça que atravessava a floresta. A fazenda agora está tomada pelos mortos. Saqueadores e escravos a serviço de {link:thule-ravenclaw}Thule Ravenclaw{/link} se reuniram ali, e caem sobre qualquer um que se aproxime. Os {link:forsaken}Renegados{/link} precisam passar por eles toda vez que tomam a estrada do sul.]=],
		},
	},
})

Translate("ptBR", "the-skittering-dark", {
	title = "Penumbra Furtiva",
	sections = {
		{
			title = "Resumo",
			text = [=[A Penumbra Furtiva é uma depressão tomada por teias no noroeste de {link:silverpine-forest}Pinhaprata{/link}, perto do mar. Grandes espreitadores do musgo e rastejadores da névoa fazem ninho ali, e ursos rondam suas bordas. Os boticários do {link:the-sepulcher}Sepulcro{/link} dão grande valor ao sangue de suas aranhas. Misturado a uma toxina tirada do coração de um urso grisalho, ele produz um elixir mortal, e a Sociedade espera que seja um passo rumo à nova praga. Um pescador renegado lança sua linha da margem próxima, como se as aranhas não fossem problema seu.]=],
		},
	},
})

Translate("ptBR", "deep-elem-mine", {
	title = "Mina Elenfunda",
	sections = {
		{
			title = "Resumo",
			text = [=[A Mina Elenfunda fica nas colinas do centro de {link:silverpine-forest}Pinhaprata{/link}, a sudeste do {link:the-sepulcher}Sepulcro{/link}. A magia de {link:archmage-arugal}Arugal{/link} se espalhou até aqui, e o próprio capataz da mina, {link:grimson-the-pale}Grimson, o Pálido{/link}, tornou-se sua vítima. Os worgens Moonrage agora dominam os túneis. Os {link:forsaken}Renegados{/link} querem a mina para a guerra que virá, pois seu minério alimentaria o avanço de {link:varimathras}Varimathras{/link} rumo ao sul. {link:dalar-dawnweaver}Dalar Dawnweaver{/link} acredita que, com o capataz morto, a mina pertencerá à Dama Sombria.]=],
		},
	},
})

Translate("ptBR", "beren-s-peril", {
	title = "Cilada de Beren",
	sections = {
		{
			title = "Resumo",
			text = [=[A Cilada de Beren é uma caverna nas colinas a sudoeste de {link:ambermill}Lenhâmbar{/link}, não longe de um acampamento dos {link:the-wizards-of-ambermill}magos de Dalaran{/link}. Os {link:forsaken}Renegados{/link} souberam por seus batedores que um bando de mortos-vivos se reunira ali. Servos braçais e guardiões a serviço de {link:thule-ravenclaw}Thule Ravenclaw{/link} preparavam um ataque contra o próprio {link:the-sepulcher}Sepulcro{/link}. O {link:shadow-priest-allister}Sacerdote das Sombras Allister{/link} não esperou que marchassem. Enviou seus próprios agentes à caverna para atacar primeiro.]=],
		},
	},
})

Translate("ptBR", "gates-of-shadowfang-keep", {
	title = "Portões da Bastilha da Presa Negra",
	sections = {
		{
			title = "Resumo",
			text = [=[A {link:shadowfang-keep}Bastilha da Presa Negra{/link} se ergue numa colina no sul de {link:silverpine-forest}Pinhaprata{/link}, logo ao norte do {link:pyrewood-village}Vilarejo Lenhardente{/link}. Era a fortaleza do {link:baron-silverlaine}Barão Silverlaine{/link}, até que os worgens a tomaram e o {link:archmage-arugal}Arquimago Arugal{/link} fez dela seu lar. Da estrada, a bastilha mostra apenas suas muralhas escuras. Os Filhos de Arugal percorrem a floresta a partir daqui, grandes worgens que servem ao arquimago como seus filhos. Os {link:forsaken}Renegados{/link} enviaram sicários para dentro. Nenhum deles voltou.]=],
		},
	},
})

Translate("ptBR", "the-greymane-wall", {
	title = "Muralha Greymane",
	sections = {
		{
			title = "Resumo",
			text = [=[A Muralha Greymane atravessa a borda sul de {link:silverpine-forest}Pinhaprata{/link} e fecha o reino de {link:gilneas}Gilneas{/link} para o norte. O {link:genn-greymane}Rei Genn Greymane{/link} a ergueu depois da {link:second-war}Segunda Guerra{/link}, e seus portões permanecem fechados desde então, mesmo quando a praga chegou. Diante da muralha, humanos que fugiram do norte fizeram um acampamento de desesperados. Muitos estão doentes. Um ferreiro cego trabalha entre eles. Worgens e worgs rondam por perto, e os {link:forsaken}Renegados{/link} temem que a maldição esteja passando aos refugiados. Os gilneanos deixaram claro que ninguém passará.]=],
		},
	},
})

Translate("ptBR", "pyrewood-villagers", {
	title = "Aldeões de Lenhardente",
	aliases = { "Conselho de Lenhardente", "amaldiçoados de Lenhardente" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os aldeões de {link:pyrewood-village}Lenhardente{/link} vivem duas vidas. De dia são humanos: vigias, anciões, ferreiros, alfaiates e coureiros cuidando de seu trabalho. Quando o sol se põe, a maldição do {link:archmage-arugal}Arquimago Arugal{/link} os domina, e eles se tornam worgens Moonrage. Cada um usa um grilhão encantado que Arugal lançou sobre eles.]=],
		},
		{
			title = "O Conselho",
			text = [=[{link:pyrewood-village}Lenhardente{/link} ainda é governada por seu conselho, oito conselheiros sob o Prefeito Morrison. Os {link:forsaken}Renegados{/link} acreditam que o conselho já não é senhor de si. {link:archmage-arugal}Arugal{/link} os usa como fantoches para manter obedientes as feras do vilarejo enquanto sua atenção está na {link:shadowfang-keep}Bastilha da Presa Negra{/link}. A {link:deathstalker-faerleia}Sicária Faerleia{/link} esperava que, com o conselho morto, os worgens se voltassem contra o próprio Arugal.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica registra se os aldeões se lembram de dia do que fazem à noite. Não está escrito quando a maldição caiu sobre eles pela primeira vez.]=],
		},
	},
})

Translate("ptBR", "the-wizards-of-ambermill", {
	title = "Os Magos de Lenhâmbar",
	aliases = { "magos de Dalaran", "Kirin Tor de Lenhâmbar" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os magos de {link:ambermill}Lenhâmbar{/link} são magos de {link:dalaran}Dalaran{/link} e os servos que os guardam: aprendizes, conjuradores, magos, vigias, guardiões e protetores, e até um mestre cervejeiro e um minerador. Respondem ao {link:kirin-tor}Kirin Tor{/link}, e fizeram de um vilarejo sonolento de {link:silverpine-forest}Pinhaprata{/link} uma fortaleza própria.]=],
		},
		{
			title = "Seu Trabalho",
			text = [=[{link:ambermill}Lenhâmbar{/link} fica sobre um nodo de energia de linhas de ley que há muito jaz adormecido. O {link:kirin-tor}Kirin Tor{/link} o escolheu por essa razão, e seu arquimago {link:archmage-ataeric}Ataeric{/link} vem tecendo suas energias para despertá-las com algum grande propósito. Os pingentes rúnicos que carregam são antigas ferramentas do Kirin Tor, usadas para canalizar tal poder. Os magos também mantêm um acampamento ao norte de {link:pyrewood-village}Lenhardente{/link}, onde chegam seus caixotes de {link:hillsbrad-foothills}Eira dos Montes{/link}.]=],
		},
		{
			title = "Entre os Vivos e os Mortos",
			text = [=[Para os {link:forsaken}Renegados{/link}, {link:ambermill}Lenhâmbar{/link} é o coração da resistência humana na floresta. Os magos montam guarda nas estradas desde que a grande barreira de {link:dalaran}Dalaran{/link} caiu, e não deixam ninguém passar livremente. O que quer que temam, não dizem.]=],
		},
	},
})

