Translate("ptBR", "genn-greymane", {
	title = "Genn Greymane",
	subtitle = "Rei de Gilneas",
	found = "Atrás da Muralha Greymane, em Gilneas",
	hint = "Saiba do rei cuja muralha fecha o sul de Pinhaprata.",
	allegiance = "Reino de Gilneas",
	aliases = { "Greymane", "Rei Greymane", "Rei Genn Greymane" },
	sections = {
		{
			title = "Resumo",
			text = [=[Genn Greymane é o rei de {link:gilneas}Gilneas{/link}. É um governante orgulhoso e teimoso, um guerreiro que confia em seu próprio povo e em poucos outros. Foi ele quem retirou Gilneas da {link:alliance}Aliança{/link} depois da {link:second-war}Segunda Guerra{/link}, e ele quem ergueu a grande muralha através do sul de {link:silverpine-forest}Pinhaprata{/link}. Por trás dessa muralha, seu reino guardou seus próprios segredos durante toda a ruína do norte.]=],
		},
		{
			title = "Importância",
			text = [=[Greymane é o senhor que escolheu ficar sozinho. Sua muralha poupou {link:gilneas}Gilneas{/link} dos custos das guerras de outras nações. Também deixou o norte enfrentar o {link:scourge}Flagelo{/link} sem o exército gilneano. Se a muralha salvou seu reino ou apenas o escondeu, ninguém de fora sabe dizer.]=],
		},
		{
			title = "Feitos",
			text = [=[• Quando {link:stormwind-city}Ventobravo{/link} caiu, veio com os outros governantes humanos ao conselho em {link:lordaeron}Lordaeron{/link} convocado pelo Rei {link:terenas-menethil}Terenas{/link}. Duvidou do perigo, e gabou-se de que o exército de {link:gilneas}Gilneas{/link} podia enfrentar qualquer ameaça.
• Uniu-se à {link:alliance}Aliança de Lordaeron{/link} com relutância, e deu a ela muito menos do que seu reino poderia ter dado.
• Depois da guerra, desentendeu-se com seus colegas reis sobre o custo dos {link:internment-camps}campos de internação{/link} dos orcs e da {link:nethergarde-keep}Bastilha de Etergarde{/link}. Quando se queixou da despesa da bastilha, o jovem Rei {link:varian-wrynn}Varian Wrynn{/link} respondeu que não se podia pôr preço na segurança deles.
• Buscou ter voz no destino de {link:alterac-mountains}Alterac{/link}, sem liderança, e apoiou um pretendente a seu trono.
• Retirou Gilneas da Aliança, construiu a {link:the-greymane-wall}Muralha Greymane{/link} e fechou seus portões.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma notícia saiu de {link:gilneas}Gilneas{/link} desde que seus portões foram fechados. O que o Rei Greymane sabe dos worgens à sua porta, e o que se passa em seu reino, nenhuma crônica destes dias sabe dizer.]=],
		},
	},
	chapters = {
		{
			title = "A Muralha de Seu Nome",
			hint = "Fique diante da muralha que leva o nome do rei.",
			text = [=[Greymane acreditava que {link:gilneas}Gilneas{/link} nada devia às guerras de outros reinos. Quando a {link:alliance}Aliança{/link} pediu a seu povo que pagasse pelos campos de prisioneiros dos orcs, ele recusou, e tirou seu reino da Aliança de vez. Depois o isolou com uma muralha. A {link:the-greymane-wall}Muralha Greymane{/link} se ergueu ao longo da fronteira norte de Gilneas. Quando a praga chegou a {link:lordaeron}Lordaeron{/link}, seus portões permaneceram fechados. Nenhum exército gilneano marchou ao norte para ajudar o reino moribundo.]=],
		},
		{
			title = "Os Portões Fechados",
			hint = [=[Ajude os Renegados a impedir que a maldição se espalhe entre os refugiados da muralha.]=],
			text = [=[Agora refugiados do norte se amontoam ao pé da muralha, doentes e famintos. Esperavam encontrar abrigo em {link:gilneas}Gilneas{/link}. Os gilneanos deixaram claro que não deixarão ninguém passar. Os {link:forsaken}Renegados{/link}, que temem a maldição dos worgens, acham isso um consolo. Dizem que ao menos a maldição não pode passar os portões.]=],
		},
	},
	mentions = {
		{ text = "Conter a Propagação" },
	},
	bonds = {
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "convocou o conselho ao qual ele se juntou" },
		{ id = "the-greymane-wall", name = "Muralha Greymane", note = "sua obra" },
	},
})
